const $=id=>document.getElementById(id);const cars=[['IONIQ 5 N','전기 트윈모터 토크의 강력한 가속력',0x8fcce4,[78,95,78]],['AVANTE N','뛰어난 코너링 핸들링 밸런스',0x77b4d4,[80,80,94]],['RN22e','미래형 에어로다이내믹 롤링랩',0xe5e8e8,[90,87,82]],['N VISION 74','드리프트 제어 특화 수소 하이브리드',0xd6dadb,[86,82,96]],['G70 N-LINE','안정적인 최고속 코너링 세단',0x455261,[88,80,86]],['GENESIS MAGMA GT','초고속 트랙 스페셜 · CONCEPT GT',0xe85b2b,[98,90,76]]];let selected=0,playing=false,started=false,elapsed=0,progress=0,laps=0,speed=0,lane=0,drift=0,boost=0,wing=0,hasWing=false,inv=0,peer,conn,remoteCar,remoteProgress=0;const keys={};let renderer,scene,camera,car,ai=[],items=[],obstacles=[],clock=new THREE.Clock();const trackLength=1600;const pos=(p,l=0)=>{let a=p*Math.PI*2;return new THREE.Vector3((220+l)*Math.sin(a),0,(120+l)*Math.cos(a))};
function mat(c,metal=.2){return new THREE.MeshStandardMaterial({color:c,metalness:metal,roughness:.45})}function box(w,h,d,c,x,y,z,parent=scene){let m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(c));m.position.set(x,y,z);parent.add(m);return m}function makeCar(color){let g=new THREE.Group();box(6,1.6,11,color,0,2,0,g);box(5,1.3,5,0x17232d,0,3.3,-.4,g);box(5.5,.22,.35,0xc6f4ff,0,2.3,-5.55,g);box(5.5,.25,.3,0xff4b39,0,2.2,5.55,g);box(.5,.16,10,0xf15442,-2,2.86,0,g);for(let x of [-3,3])for(let z of [-3.5,3.5]){let wheel=new THREE.Mesh(new THREE.CylinderGeometry(1.4,1.4,1.2,16),mat(0x14191d));wheel.rotation.z=Math.PI/2;wheel.position.set(x,1.4,z);g.add(wheel);let hub=new THREE.Mesh(new THREE.CylinderGeometry(.75,.75,1.25,12),mat(0x9baab1,.8));hub.rotation.z=Math.PI/2;hub.position.copy(wheel.position);g.add(hub)}box(7,.25,1,0x1b252b,0,4.1,4.6,g);g.userData.wings=[];for(let x of [-1,1]){let w=box(5,.16,2,0x9cd8ed,x*4.5,2.5,1,g);w.visible=false;g.userData.wings.push(w)}scene.add(g);return g}
function init(){scene=new THREE.Scene();scene.background=new THREE.Color(0x91bac7);scene.fog=new THREE.Fog(0x91bac7,350,1050);camera=new THREE.PerspectiveCamera(52,innerWidth/innerHeight,.1,2000);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;$('scene').appendChild(renderer.domElement);scene.add(new THREE.HemisphereLight(0xcfeeff,0x586750,2));let sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(100,200,100);scene.add(sun);box(2000,2,2000,0x557d72,0,-3,0);let segments=240;for(let i=0;i<segments;i++){let p=i/segments,q=(i+1)/segments,a=pos(p),b=pos(q),mid=a.clone().add(b).multiplyScalar(.5),angle=Math.atan2(b.x-a.x,b.z-a.z),len=a.distanceTo(b)+1;let road=box(32,.3,len,0x303a3d,mid.x,0,mid.z);road.rotation.y=angle;for(let side of [-1,1]){let v=pos((p+q)/2,side*16);let curb=box(1,.6,len, i%2?0xe85143:0xe6eeee,v.x,.35,v.z);curb.rotation.y=angle;let wall=box(.7,2.4,len,0xa8c2c7,v.x,.9,v.z);wall.rotation.y=angle}if(i%4===0){let line=box(.35,.05,len*.48,0xc6d2d0,mid.x,.2,mid.z);line.rotation.y=angle}}
for(let i=0;i<48;i++){let p=i/48;for(let s of [-1,1]){let v=pos(p,s*27);let trunk=box(1,6,1,0x655948,v.x,3,v.z);let crown=new THREE.Mesh(new THREE.ConeGeometry(5,12,7),mat(i%2?0x386a5a:0x467e67));crown.position.set(v.x,12,v.z);scene.add(crown)}}for(let i=0;i<7;i++){let v=pos(i/7+.05,0);let a=(i/7+.05)*Math.PI*2;let gate=new THREE.Group();box(1,15,1,0x9fe7fa,-17,7.5,0,gate);box(1,15,1,0x9fe7fa,17,7.5,0,gate);box(35,1,1,0x9fe7fa,0,15,0,gate);gate.position.copy(v);gate.rotation.y=Math.atan2(220*Math.cos(a),-120*Math.sin(a));scene.add(gate)}for(let i=0;i<12;i++){let v=pos(i/12+.025,i%2?5:-5);let mesh=box(2.5,3,2.5,i%3===0?0x72d9ff:0xffa137,v.x,2,v.z);mesh.rotation.y=.7;items.push({mesh,p:i/12+.025,l:i%2?5:-5,type:i%3===0?'wing':'fuel',used:0})}for(let i=0;i<9;i++){let p=i/9+.07,l=i%2?8:-7,v=pos(p,l);let m=new THREE.Mesh(new THREE.ConeGeometry(1.4,3,8),mat(0xff773b));m.position.set(v.x,1.5,v.z);scene.add(m);obstacles.push({p,l})}for(let i=0;i<4;i++){let v=pos(.18+i*.025,35);box(15,8+i*3,12,0x70858a,v.x,4+i*1.5,v.z)}car=makeCar(cars[0][2]);for(let i=0;i<3;i++)ai.push({mesh:makeCar([0xf15442,0xf0eddf,0x4a7185][i]),p:-.01-i*.012,l:(i-1)*7,rate:.000104+i*.000003});window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});animate()}
function orient(mesh,p,l,y=0){let v=pos(p,l),next=pos(p+.001,l);mesh.position.set(v.x,y,v.z);mesh.rotation.y=Math.atan2(next.x-v.x,next.z-v.z)+Math.PI}function select(n){selected=(n+cars.length)%cars.length;let c=cars[selected];$('carName').textContent=c[0];$('carDesc').textContent=c[1];$('carNum').innerHTML=String(selected+1).padStart(2,'0')+' <span>/ 06</span>';c[3].forEach((v,i)=>$('s'+(i+1)).style.width=v+'%');$('dots').innerHTML=cars.map((_,i)=>`<i class="${i===selected?'active':''}"></i>`).join('');car.children[0].material.color.setHex(c[2])}function start(){playing=true;started=false;elapsed=0;progress=0;laps=0;speed=0;lane=0;drift=0;boost=0;wing=0;hasWing=false;ai.forEach((a,i)=>a.p=-.01-i*.012);$('menu').classList.add('hidden');$('lobby').classList.add('hidden');$('finish').classList.add('hidden');$('hud').classList.remove('hidden');document.body.classList.add('racing');let n=3;$('countdown').textContent=n;let t=setInterval(()=>{n--;if(n>0)$('countdown').textContent=n;else if(n===0){$('countdown').textContent='GO!';started=true}else{$('countdown').textContent='';clearInterval(t)}},800)}function quit(){playing=false;started=false;document.body.classList.remove('racing');$('hud').classList.add('hidden');$('finish').classList.add('hidden');$('menu').classList.remove('hidden')}function notice(s){$('message').textContent=s;setTimeout(()=>{if($('message').textContent===s)$('message').textContent=''},1500)}function format(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0')+'.'+String(Math.floor(t%1*100)).padStart(2,'0')}
function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.05),now=performance.now()/1000;items.forEach(it=>{it.mesh.rotation.y+=dt;it.mesh.visible=now>it.used});if(playing){if(started){elapsed+=dt;let accel=keys.ArrowUp||keys.KeyW;speed+=(accel?48:-30)*dt;if(keys.ArrowDown||keys.KeyS)speed-=80*dt;speed=Math.max(0,Math.min(speed,boost>0?270:175+cars[selected][3][0]*.25));let steer=(keys.ArrowRight||keys.KeyD?1:0)-(keys.ArrowLeft||keys.KeyA?1:0);lane+=steer*dt*(keys.ShiftLeft||keys.ShiftRight?14:10)*Math.min(speed/40,1);lane=Math.max(-14,Math.min(14,lane));if((keys.ShiftLeft||keys.ShiftRight)&&steer&&speed>50){drift+=dt*24;if(drift>=100){drift=0;boost=3;notice('DRIFT BOOST!')}}if(boost>0)boost-=dt;if(wing>0)wing-=dt;if(inv>0)inv-=dt;progress+=speed*dt/3600*1000/trackLength;ai.forEach(a=>a.p+=dt*a.rate*60);for(let it of items){let diff=Math.abs((progress%1)-it.p);if(diff<.007&&Math.abs(lane-it.l)<5&&now>it.used){it.used=now+12;if(it.type==='fuel'){boost=5;notice('HYPER BOOST!')}else{hasWing=true;notice('WING ITEM ACQUIRED · SPACE')}}}for(let o of obstacles){if(Math.abs(progress%1-o.p)<.005&&Math.abs(lane-o.l)<4&&inv<=0&&wing<=0){speed*=.72;inv=2;notice('COLLISION!')}}if(progress>=2){started=false;playing=false;$('hud').classList.add('hidden');$('finish').classList.remove('hidden');$('result').textContent='FINISH '+$('position').innerText;$('resultTime').textContent='YOUR TIME  '+format(elapsed)}if(conn&&conn.open)conn.send({p:progress,l:lane,s:speed});}
orient(car,progress%1,lane,wing>0?10+Math.sin(now*3):0);car.userData.wings.forEach(w=>w.visible=wing>0);ai.forEach(a=>orient(a.mesh,((a.p%1)+1)%1,a.l));if(remoteCar)orient(remoteCar,remoteProgress%1,0);let ahead=pos((progress+.015)%1,lane),behind=pos((progress-.025+1)%1,lane);camera.position.lerp(new THREE.Vector3(behind.x,22+(wing>0?8:0),behind.z),.08);camera.lookAt(ahead.x,3+(wing>0?8:0),ahead.z);$('speed').textContent=Math.round(speed);$('timer').textContent=format(elapsed);$('lap').innerHTML=Math.min(2,Math.floor(progress)+1)+' <span>/ 2</span>';$('boostBar').style.width=drift+'%';$('item').textContent=wing>0?'WING — ACTIVE':hasWing?'WING — SPACE TO USE':'WING — EMPTY';let rank=1+ai.filter(a=>a.p>progress).length+(conn&&remoteProgress>progress?1:0);$('position').innerHTML=rank+'<sup>'+(['','ST','ND','RD','TH','TH'][rank])+'</sup><span> / '+(conn?5:4)+'</span>'}else{let t=now*.08;orient(car,.10,0);ai.forEach(a=>a.mesh.visible=false);let v=pos(.1);camera.position.set(v.x+Math.cos(t)*35,15,v.z+Math.sin(t)*35);camera.lookAt(v.x,3,v.z)}if(playing)ai.forEach(a=>a.mesh.visible=true);renderer.render(scene,camera)}
$('prev').onclick=()=>select(selected-1);$('next').onclick=()=>select(selected+1);$('start').onclick=start;$('again').onclick=quit;$('quit').onclick=quit;$('multi').onclick=()=>{$('lobby').classList.remove('hidden')};$('closeLobby').onclick=()=>$('lobby').classList.add('hidden');window.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Space'&&hasWing&&playing){hasWing=false;wing=6;notice('WINGS DEPLOYED!')}if(e.code==='Escape'&&playing)quit()});window.addEventListener('keyup',e=>keys[e.code]=false);
function setupConnection(c){conn=c;c.on('open',()=>{$('networkStatus').textContent='상대방과 연결되었습니다. 방장이 레이스를 시작하세요.';$('onlineStart').classList.remove('hidden');if(!remoteCar)remoteCar=makeCar(0xffce56)});c.on('data',d=>{if(d.start)start();if(typeof d.p==='number')remoteProgress=d.p});c.on('close',()=>{$('networkStatus').textContent='상대방 연결이 종료되었습니다.'})}function makePeer(cb){if(!window.Peer){$('networkStatus').textContent='PeerJS를 불러오지 못했습니다. 인터넷 연결을 확인하세요.';return}peer=new Peer();peer.on('open',cb);peer.on('connection',setupConnection);peer.on('error',e=>$('networkStatus').textContent='연결 오류: '+e.type)}$('host').onclick=()=>makePeer(id=>{let url=location.origin+location.pathname+'?room='+id;$('room').value=url;$('networkStatus').textContent='초대 링크를 복사해 친구에게 보내세요.';navigator.clipboard?.writeText(url).catch(()=>{})});$('join').onclick=()=>{let input=$('room').value.trim(),id=input.includes('room=')?new URL(input).searchParams.get('room'):input;if(!id){$('networkStatus').textContent='초대 링크 또는 방 ID를 입력하세요.';return}makePeer(()=>setupConnection(peer.connect(id)))};$('onlineStart').onclick=()=>{if(conn?.open)conn.send({start:true});start()};let room=new URLSearchParams(location.search).get('room');if(room){$('lobby').classList.remove('hidden');$('room').value=room;$('networkStatus').textContent='참가 버튼을 눌러 방에 연결하세요.'}init();select(0);
